import{_ as i,C as e,o as t,c as r,a2 as s,E as o}from"./chunks/framework.CCtxZRER.js";const b=JSON.parse('{"title":"Yang Perlu Dikonfirmasi","description":"Daftar pertanyaan dan dokumen yang perlu diminta dari pembimbing magang.","frontmatter":{"title":"Yang Perlu Dikonfirmasi","description":"Daftar pertanyaan dan dokumen yang perlu diminta dari pembimbing magang.","status":"ditinjau","dasar":"hasil penyusunan handbook versi awal","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Tentang Handbook","kata_kunci":["verifikasi","pertanyaan untuk pembimbing","data yang kurang","belum lengkap","to do"]},"headers":[],"relativePath":"tentang-handbook/perlu-verifikasi.md","filePath":"tentang-handbook/perlu-verifikasi.md"}'),l={name:"tentang-handbook/perlu-verifikasi.md"};function g(u,a,d,k,m,p){const n=e("TabelStatus");return t(),r("div",null,[a[0]||(a[0]=s('<h1 id="yang-perlu-dikonfirmasi" tabindex="-1">Yang Perlu Dikonfirmasi <a class="header-anchor" href="#yang-perlu-dikonfirmasi" aria-label="Permalink to &quot;Yang Perlu Dikonfirmasi&quot;">​</a></h1><p class="lead">Daftar ini bisa dibawa saat bertemu pembimbing. Setelah sebuah poin terjawab, perbarui file terkait dan centang poinnya di versi berikutnya.</p><h2 id="tentang-perusahaan" tabindex="-1">Tentang perusahaan <a class="header-anchor" href="#tentang-perusahaan" aria-label="Permalink to &quot;Tentang perusahaan&quot;">​</a></h2><ul class="daftar-periksa"><li><strong>Visi dan misi resmi</strong> beserta dokumen atau tautan sumbernya.</li><li><strong>Tahun berdiri dan sejarah singkat</strong> BPI.</li><li><strong>Nilai perusahaan.</strong> Apakah <em>Passion, Respect, Integrity, Discipline, Excellent</em> adalah nilai resmi perusahaan atau motto Gudang Teknik?</li><li><strong>Produk utama</strong>: jenis pipa, rentang ukuran, dan standar yang boleh dicantumkan.</li><li><strong>Struktur organisasi</strong> yang boleh ditampilkan, minimal di tingkat departemen.</li><li><strong>Sertifikasi</strong> yang masih berlaku.</li><li><strong>Alamat situs resmi</strong> perusahaan untuk dijadikan sumber utama.</li></ul><h2 id="tentang-gudang-teknik" tabindex="-1">Tentang Gudang Teknik <a class="header-anchor" href="#tentang-gudang-teknik" aria-label="Permalink to &quot;Tentang Gudang Teknik&quot;">​</a></h2><ul class="daftar-periksa"><li><strong>Denah layout gudang</strong> (slide 7 presentasi Gudang Teknik).</li><li><strong>Kepanjangan &quot;OS&quot;</strong> pada divisi OS/PPIC, supaya bisa dijelaskan di Kamus Istilah.</li><li><strong>Format surat tanda terima</strong> dan laporan barang masuk ke OS/PPIC (boleh contoh kosong tanpa data asli).</li><li><strong>Bagian ERP</strong> yang boleh diakses peserta magang.</li><li><strong>Aturan pengodean barang</strong> resmi, misalnya arti setiap bagian <code>BRG-MEC-001</code>.</li><li><strong>Parameter stok</strong>: cara gudang menetapkan stok minimum, maksimum, ROP, dan safety stock.</li><li><strong>Kategori material yang tidak diminta</strong> sama sekali dalam sebulan.</li><li><strong>Jadwal stock opname</strong> dan cycle counting.</li><li><strong>Siapa yang memesan barang ke vendor</strong> (alur sebelum barang datang).</li></ul><h2 id="tentang-sop-dan-k3" tabindex="-1">Tentang SOP dan K3 <a class="header-anchor" href="#tentang-sop-dan-k3" aria-label="Permalink to &quot;Tentang SOP dan K3&quot;">​</a></h2><ul class="daftar-periksa"><li>Apakah ada <strong>SOP resmi</strong> untuk penyimpanan, stock opname, dan write off? Jika ada, judul dan nomornya.</li><li>Persetujuan pembimbing untuk <strong>SOP Penerimaan dan Pengeluaran Barang</strong> yang sudah disesuaikan dengan alur kerja.</li><li><strong>APD wajib</strong> di setiap area gudang.</li><li><strong>Area terbatas</strong> untuk peserta magang.</li><li><strong>Nomor darurat, lokasi APAR dan P3K, jalur evakuasi, dan titik kumpul.</strong></li><li><strong>Aturan limbah</strong> untuk consumable yang bocor atau kedaluwarsa.</li></ul><h2 id="tentang-magang-dan-publikasi" tabindex="-1">Tentang magang dan publikasi <a class="header-anchor" href="#tentang-magang-dan-publikasi" aria-label="Permalink to &quot;Tentang magang dan publikasi&quot;">​</a></h2><ul class="daftar-periksa"><li><strong>Aturan jam kerja, absensi, dan izin</strong> peserta magang.</li><li><strong>Izin penggunaan logo dan warna</strong> perusahaan di website, termasuk file logo resmi dan kode warnanya.</li><li>[x] <strong>Izin publikasi</strong>: apakah website boleh diakses publik, hanya jaringan internal, atau hanya dijalankan lokal.</li><li>[x] <strong>Foto dan screenshot</strong> yang boleh dimuat.</li></ul><h2 id="rekap-status-semua-halaman" tabindex="-1">Rekap status semua halaman <a class="header-anchor" href="#rekap-status-semua-halaman" aria-label="Permalink to &quot;Rekap status semua halaman&quot;">​</a></h2>',11)),o(n,{kolom:"status"})])}const c=i(l,[["render",g]]);export{b as __pageData,c as default};
